#include "dht11.h"

/* TIM2 handle generated by CubeMX */
extern TIM_HandleTypeDef htim2;

/* DHT11 pin configuration */
#define DHT11_PORT       GPIOA
#define DHT11_PIN        GPIO_PIN_1

/* Wait for a GPIO level with timeout */
static uint8_t DHT11_WaitForLevel(GPIO_PinState level,
                                  uint32_t timeout_us)
{
    uint32_t start = __HAL_TIM_GET_COUNTER(&htim2);

    while (HAL_GPIO_ReadPin(DHT11_PORT, DHT11_PIN) != level)
    {
        uint32_t now = __HAL_TIM_GET_COUNTER(&htim2);

        if ((uint32_t)(now - start) >= timeout_us)
        {
            return 0;
        }
    }

    return 1;
}

/* Configure DATA pin as output open drain */
static void DHT11_SetOutput(void)
{
    GPIO_InitTypeDef GPIO_InitStruct = {0};

    GPIO_InitStruct.Pin = DHT11_PIN;
    GPIO_InitStruct.Mode = GPIO_MODE_OUTPUT_OD;
    GPIO_InitStruct.Pull = GPIO_PULLUP;
    GPIO_InitStruct.Speed = GPIO_SPEED_FREQ_LOW;

    HAL_GPIO_Init(DHT11_PORT, &GPIO_InitStruct);
}

/* Configure DATA pin as input */
static void DHT11_SetInput(void)
{
    GPIO_InitTypeDef GPIO_InitStruct = {0};

    GPIO_InitStruct.Pin = DHT11_PIN;
    GPIO_InitStruct.Mode = GPIO_MODE_INPUT;
    GPIO_InitStruct.Pull = GPIO_PULLUP;

    HAL_GPIO_Init(DHT11_PORT, &GPIO_InitStruct);
}

/* Initialize DHT11 */
void DHT11_Init(void)
{
    DHT11_SetOutput();

    HAL_GPIO_WritePin(DHT11_PORT, DHT11_PIN, GPIO_PIN_SET);
}

/* Send start signal */
static void DHT11_Start(void)
{
    DHT11_SetOutput();

    /* Pull DATA LOW for at least 18 ms */
    HAL_GPIO_WritePin(DHT11_PORT, DHT11_PIN, GPIO_PIN_RESET);

    HAL_Delay(20);

    /* Release DATA line */
    HAL_GPIO_WritePin(DHT11_PORT, DHT11_PIN, GPIO_PIN_SET);

    delay_us:
    __HAL_TIM_SET_COUNTER(&htim2, 0);
    while (__HAL_TIM_GET_COUNTER(&htim2) < 30);

    DHT11_SetInput();
}

/* Check sensor response */
static uint8_t DHT11_CheckResponse(void)
{
    /* Sensor response LOW: approximately 80 us */
    if (!DHT11_WaitForLevel(GPIO_PIN_RESET, 100))
        return 0;

    /* Sensor response HIGH: approximately 80 us */
    if (!DHT11_WaitForLevel(GPIO_PIN_SET, 100))
        return 0;

    /* Wait until response HIGH ends */
    if (!DHT11_WaitForLevel(GPIO_PIN_RESET, 100))
        return 0;

    return 1;
}

/* Read one data bit */
static uint8_t DHT11_ReadBit(void)
{
    uint32_t start;
    uint32_t pulse_width;

    /* Wait for the beginning of HIGH pulse */
    if (!DHT11_WaitForLevel(GPIO_PIN_SET, 100))
        return 0;

    start = __HAL_TIM_GET_COUNTER(&htim2);

    /* Measure HIGH pulse duration */
    if (!DHT11_WaitForLevel(GPIO_PIN_RESET, 100))
        return 0;

    pulse_width = (uint32_t)
        (__HAL_TIM_GET_COUNTER(&htim2) - start);

    /* HIGH pulse > 40 us represents bit 1 */
    return (pulse_width > 40) ? 1 : 0;
}

/* Read one byte */
static uint8_t DHT11_ReadByte(void)
{
    uint8_t value = 0;

    for (uint8_t i = 0; i < 8; i++)
    {
        value <<= 1;
        value |= DHT11_ReadBit();
    }

    return value;
}

/* Read temperature and humidity */
uint8_t DHT11_ReadData(DHT11_Data_t *data)
{
    uint8_t raw[5];

    if (data == NULL)
        return 0;

    DHT11_Start();

    if (!DHT11_CheckResponse())
        return 0;

    /* Receive 40 bits */
    for (uint8_t i = 0; i < 5; i++)
    {
        raw[i] = DHT11_ReadByte();
    }

    /* Checksum verification */
    uint8_t calculated_checksum =
        raw[0] + raw[1] + raw[2] + raw[3];

    if (calculated_checksum != raw[4])
        return 0;

    /* Extract integer values */
    data->humidity = raw[0];
    data->temperature = raw[2];

    return 1;
}